def orientations(shape, marker=None):
    h=max(r for r,c in shape)+1; w=max(c for r,c in shape)+1
    out={}
    for refl in [False,True]:
        for k in range(4):
            pts=set(shape); m=marker
            hh,ww=h,w
            if refl:
                pts={(r,ww-1-c) for r,c in pts}
                if m: m=(m[0],ww-1-m[1])
            for _ in range(k):
                pts={(c,hh-1-r) for r,c in pts}
                if m: m=(m[1],hh-1-m[0])
                hh,ww=ww,hh
            rr=min(r for r,c in pts); cc=min(c for r,c in pts)
            pts=frozenset((r-rr,c-cc) for r,c in pts)
            if m: m=(m[0]-rr,m[1]-cc)
            key=(pts,m)
            out[key]=(hh,ww)
    return [(p,m,dims) for (p,m),dims in out.items()]
