# Generic exact-cover enumerator for small demos

def solve_shapes(shapes, marker_col, side, max_solutions=10000):
    global H,W
    H=W=side
    o={col:orientations(shape,mark) for col,(shape,mark) in shapes.items()}
    mopts=[]
    for oi,(s,m,d) in enumerate(o[marker_col]):
        if m==(0,0) and d[0]<=H and d[1]<=W:
            mopts.append((oi,mask_for(s,0,0)))
    allsol=[]
    rest=[x for x in shapes if x!=marker_col]
    for moi,fixed in mopts:
        cs={}
        for col in rest:
            cs[col]=[]
            for oi,(s,m,d) in enumerate(o[col]):
                hh,ww=d
                for r in range(H-hh+1):
                    for c in range(W-ww+1):
                        mm=mask_for(s,r,c)
                        if not(mm&fixed): cs[col].append((oi,r,c,mm))
        # brute recursively
        def rec(i, used, chosen):
            if len(allsol)>=max_solutions:return
            if i==len(rest):
                allsol.append((moi,dict(chosen)))
                return
            col=rest[i]
            for cand in cs[col]:
                if not cand[3]&used:
                    rec(i+1,used|cand[3],chosen+[(col,cand)])
        rec(0,fixed,[])
    return o,allsol

